def crack_safe(numbers):
    def is_even(n):
        return n % 2 == 0

    def make_equal(nums):
        while not all(n == nums[0] for n in nums):
            if is_even(nums[0]) and is_even(nums[1]):
                nums[0] //= 2
                nums[1] //= 2
                yield '/1'
            else:
                nums[0] += 1
                nums[1] += 1
                yield '+1'

    def find_operations(nums):
        operations = []
        while not all(n == nums[0] for n in nums):
            if is_even(nums[0]) and is_even(nums[1]):
                nums[0] //= 2
                nums[1] //= 2
                operations.append('/1')
            else:
                nums[0] += 1
                nums[1] += 1
                operations.append('+1')
        return operations

    operations = find_operations(numbers[:])
    if all(n == numbers[0] for n in numbers):
        return "\n".join(operations)
    else:
        return "-1"

